 Check(!Scene->LoadStarCatalogue(".cache/nonexistent-stars.bin"),"missing catalogue degrades safely");Scene->BuildSheet(CelestialEntity::Stars,*Sheet);Check(Sheet->StarPreview.Count==0&&Pack().PostStar[3]==0,"missing catalogue renders no invented stars");Rest();Capture("Stars-Unavailable");Scene->BuildSheet(CelestialEntity::Moons,*Sheet);Check(!Sheet->StarPreview.Records&&Sheet->StarPreview.Count==0,"sheet reuse clears borrowed stars");ImGui::DestroyContext();std::printf("PASS %u checks: native Stars, real catalogue, bindings, signal, ABI, pointer/keyboard input, responsive layout and teardown. No scene-camera/GPU execution claim.\n",Checks);
